def pt(key: str, lang: str = "en", **kwargs) -> str:
    """Translate workflow text, with the existing English UI fallback."""
    values = TEXT.get(key)
    if not values:
        return key
    index = {"zh": 0, "ja": 2}.get(lang, 1)
    return values[index].format(**kwargs)
